  */
 bool crea_cow_condivisa()
 {
-/// @todo creare la prima copia della zona cow
-// ( SOLUZIONE 2023-06-07
-//   SOLUZIONE 2023-06-07 )
+	// Allochiamo la tabella radice di livello 4 per la zona cow
+	cow_root = alloca_tab();
+	if (!cow_root)
+		return false;
+
+	vaddr begin = ini_utn_w;
+	vaddr end = begin + DIM_USR_COW;
+
+	// Mappiamo l'intera zona cow con frame allocati, in sola lettura (BIT_US ma non BIT_RW)
+	// I frame devono essere azzerati (la zona deve inizialmente contenere solo byte nulli)
+	vaddr v = map(cow_root, begin, end, BIT_US,
+		      [](vaddr) {
+			paddr f = alloca_frame();
+			if (f)
+				memset(voidptr_cast(f), 0, DIM_PAGINA);
+			return f;
+		      });
+
+	if (v != end) {
+		// In caso di errore, deallochiamo quanto creato
+		unmap(cow_root, begin, v,
+		      [](vaddr, paddr p, int) { rilascia_frame(p); });
+		rilascia_tab(cow_root);
+		cow_root = 0;
+		return false;
+	}
+
+	return true;
 }

