@@ -848,8 +873,67 @@ void copia_cow_condivisa(paddr dest)
 // dal processo corrente
 bool aggiorna_cow_privata(vaddr v)
 {
-// ( SOLUZIONE 2023-06-07
-//   SOLUZIONE 2023-06-07 )
+	// Controlla se v appartiene alla zona utente/cow
+	if (v < ini_utn_w || v >= ini_utn_w + DIM_USR_COW)
+		return false;
+
+	paddr tab = esecuzione->cr3;
+
+	// Percorriamo l'albero di traduzione dal livello MAX_LIV fino al livello 1
+	for (int liv = MAX_LIV; liv >= 1; liv--) {
+		int idx = i_tab(v, liv);
+		tab_entry e = get_entry(tab, idx);
+
+		if (!(e & BIT_P))
+			return false;
+
+		if (liv == 1) {
+			// Siamo al livello delle pagine (foglia): copiamo il frame e abilitiamo la scrittura
+			if (e & BIT_RW)
+				return true; // gia' scrivibile
+
+			paddr old_frame = extr_IND_FISICO(e);
+			paddr new_frame = alloca_frame();
+			if (!new_frame)
+				return false;
+
+			// Copia il contenuto del vecchio frame nel nuovo
+			memcpy(voidptr_cast(new_frame), voidptr_cast(old_frame), DIM_PAGINA);
+
+			// Aggiorna l'entrata: nuovo frame, bit RW settato
+			tab_entry new_e = new_frame | BIT_P | BIT_RW | BIT_US;
+			set_entry(tab, idx, new_e);
+
+			// Invalida la traduzione nel TLB per questo indirizzo
+			invalida_entrata_TLB(v);
+
+			return true;
+		}
+
+		// Livello non foglia
+		if (e & BIT_RW) {
+			// L'entrata punta gia' a una tabella privata
+			tab = extr_IND_FISICO(e);
+			continue;
+		}
+
+		// L'entrata punta a una tabella condivisa: creiamo una copia privata
+		paddr shared_tab = extr_IND_FISICO(e);
+		paddr new_tab = alloca_tab();
+		if (!new_tab)
+			return false;
+
+		// Copia tutte le voci dalla tabella condivisa in quella privata
+		copy_des(shared_tab, new_tab, 0, 512);
+
+		// Aggiorna l'entrata per puntare alla nuova tabella privata (con BIT_RW)
+		tab_entry new_e = new_tab | BIT_P | BIT_RW | BIT_US;
+		set_entry(tab, idx, new_e);
+
+		tab = new_tab;
+	}
+
+	return false;
 }

